// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(address migratorAddr, address rewardToken) public {
        vm.assume(rewardToken != address(0) && rewardToken != address(this));
        vm.assume(migratorAddr != address(0));

        // Set a non-zero migrator, then call addReward
        c.setMigrator(migratorAddr);
        c.addReward(rewardToken);

        // The rule: after addReward, migrator should still be the value we set
        assertTrue(c.migrator() == migratorAddr);
    }
}

